"use client";

import { cn } from "cn";
import { format } from "date-fns";
import type { Locale } from "date-fns";
import { CalendarClock } from "lucide-react";
import * as React from "react";
import type { Matcher } from "react-day-picker";

import { Button } from "./button";
import { Calendar } from "./calendar";
import { PickerFooter, TimeField } from "./date-time-picker-parts";
import type { TimeUnitLabels } from "./date-time-picker-parts";
import {
  defaultTimeValue,
  formatTimeValue,
  mergeDateAndTime,
  normalizeDateTime,
  parseTimeValue,
  resolveHourCycle,
} from "./date-time-picker-utils";
import type { DateTimePrecision, HourCycle } from "./date-time-picker-utils";
import {
  Popover,
  PopoverContent,
  PopoverTitle,
  PopoverTrigger,
} from "./popover";

// Composes Vandor's Button, Popover and Calendar with a Vandor time field. Values are
// local-time `Date`s; the draft is committed only by Apply (or Clear).

export type { DateTimePrecision, HourCycle, TimeUnitLabels };

export interface DateTimePickerProps {
  id?: string;
  label: string;
  placeholder?: string;
  clearable?: boolean;
  value?: Date;
  defaultValue?: Date;
  onValueChange?: (date: Date | undefined) => void;
  locale?: Locale;
  dateFormat?: string;
  precision?: DateTimePrecision;
  hourCycle?: HourCycle;
  timeUnitLabels?: TimeUnitLabels;
  disabled?: boolean;
  readOnly?: boolean;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  disabledDates?: Matcher | Matcher[];
  startMonth?: Date;
  endMonth?: Date;
  timeLabel?: string;
  applyLabel?: string;
  cancelLabel?: string;
  clearLabel?: string;
  className?: string;
  motion?: boolean;
}

const withPickerDefaults = ({
  placeholder = "Select date and time",
  clearable = false,
  dateFormat = "PPP p",
  precision = "minute",
  defaultOpen = false,
  timeLabel = "Time",
  applyLabel = "Apply",
  cancelLabel = "Cancel",
  clearLabel = "Clear",
  motion = true,
  ...props
}: DateTimePickerProps) => ({
  ...props,
  applyLabel,
  cancelLabel,
  clearLabel,
  clearable,
  dateFormat,
  defaultOpen,
  motion,
  placeholder,
  precision,
  timeLabel,
});

export const DateTimePicker = (props: DateTimePickerProps) => {
  const {
    id,
    label,
    placeholder,
    clearable,
    value,
    defaultValue,
    onValueChange,
    locale,
    dateFormat,
    precision,
    hourCycle,
    timeUnitLabels,
    disabled,
    readOnly,
    open,
    defaultOpen,
    onOpenChange,
    disabledDates,
    startMonth,
    endMonth,
    timeLabel,
    applyLabel,
    cancelLabel,
    clearLabel,
    className,
    motion,
  } = withPickerDefaults(props);
  const blocked = Boolean(disabled || readOnly);
  const controlled = Object.hasOwn(props, "value");
  const generatedId = React.useId();
  const triggerId = id ?? generatedId;
  const [internal, setInternal] = React.useState(defaultValue);
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen);
  const committed = controlled ? value : internal;
  const isOpen = !disabled && (open === undefined ? internalOpen : open);
  React.useEffect(() => {
    if (disabled) {
      setInternalOpen(false);
    }
  }, [disabled]);

  const fromCommitted = () => ({
    day: committed,
    time: committed
      ? formatTimeValue(committed, precision)
      : defaultTimeValue("start", precision),
  });
  const [draft, setDraft] = React.useState(fromCommitted);
  // The draft mirrors the committed value whenever the popup is closed, so a reopen
  // (including a controlled `open`) never shows a discarded or stale edit.
  const resetDraft = React.useEffectEvent(() => setDraft(fromCommitted()));
  const committedTime = committed?.getTime();
  React.useEffect(() => {
    if (!isOpen) {
      resetDraft();
    }
  }, [isOpen, committedTime, precision]);

  const setOpen = (next: boolean) => {
    if (disabled && next) {
      return;
    }
    if (open === undefined) {
      setInternalOpen(next);
    }
    onOpenChange?.(next);
  };
  const commit = (next?: Date) => {
    if (blocked) {
      return;
    }
    if (!controlled) {
      setInternal(next);
    }
    onValueChange?.(next);
    setOpen(false);
  };

  const parsedTime = parseTimeValue(draft.time);
  const canApply =
    !blocked && draft.day !== undefined && parsedTime !== undefined;
  const apply = () => {
    if (canApply && draft.day && parsedTime) {
      commit(mergeDateAndTime(draft.day, parsedTime, precision));
    }
  };
  const whileTap = motion ? { scale: 0.96 } : false;
  const shown = committed
    ? format(normalizeDateTime(committed, precision), dateFormat, { locale })
    : placeholder;

  return (
    <div data-slot="date-time-picker" className="grid min-w-0 gap-1.5">
      <label
        htmlFor={triggerId}
        id={`${triggerId}-label`}
        className="text-sm font-medium"
      >
        {label}
      </label>
      <Popover open={isOpen} onOpenChange={setOpen}>
        <PopoverTrigger
          id={triggerId}
          disabled={disabled}
          aria-labelledby={`${triggerId}-label ${triggerId}-value`}
          render={<Button variant="outline" whileTap={whileTap} />}
          className={cn(
            "inline-flex h-9 min-w-0 items-center justify-start gap-2 rounded-md border border-input bg-background px-3 text-sm font-normal shadow-xs outline-none hover:bg-accent focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 dark:bg-input/30",
            className
          )}
        >
          <CalendarClock aria-hidden="true" className="size-4 shrink-0" />
          <span
            id={`${triggerId}-value`}
            className={cn("truncate", !committed && "text-muted-foreground")}
          >
            {shown}
          </span>
        </PopoverTrigger>
        <PopoverContent
          align="start"
          animated={motion}
          className="w-auto gap-0 p-0"
        >
          <PopoverTitle className="sr-only">{label}</PopoverTitle>
          <div className="flex flex-col sm:flex-row">
            <Calendar
              mode="single"
              motion={motion}
              autoFocus
              defaultMonth={draft.day}
              locale={locale}
              selected={draft.day}
              disabled={blocked ? () => true : disabledDates}
              startMonth={startMonth}
              endMonth={endMonth}
              onSelect={(day) => {
                // Re-clicking the selected day must not empty the draft.
                if (day && !blocked) {
                  setDraft((current) => ({ ...current, day }));
                }
              }}
            />
            <div className="border-t p-3 sm:border-t-0 sm:border-l">
              <TimeField
                id={`${triggerId}-time`}
                label={timeLabel}
                value={draft.time}
                precision={precision}
                hourCycle={resolveHourCycle(locale, hourCycle)}
                locale={locale}
                unitLabels={timeUnitLabels}
                disabled={disabled}
                readOnly={readOnly}
                onEnter={apply}
                onValueChange={(time) =>
                  setDraft((current) => ({ ...current, time }))
                }
              />
            </div>
          </div>
          <div className="border-t p-3">
            <PickerFooter
              showClear={Boolean(clearable && committed && !blocked)}
              canApply={canApply}
              whileTap={whileTap}
              labels={{
                apply: applyLabel,
                cancel: cancelLabel,
                clear: clearLabel,
              }}
              onClear={() => commit()}
              onCancel={() => setOpen(false)}
              onApply={apply}
            />
          </div>
        </PopoverContent>
      </Popover>
    </div>
  );
};

"use client";

import { cn } from "cn";
import { format } from "date-fns";
import type { Locale } from "date-fns";
import * as React from "react";

import { Button } from "./button";
import {
  from12Hour,
  parseTimeValue,
  to12Hour,
  withTimePart,
} from "./date-time-picker-utils";
import type {
  DateTimePrecision,
  HourCycle,
  TimePart,
} from "./date-time-picker-utils";

// Pieces shared by DateTimePicker and DateTimeRangePicker: a time of day picked from
// scrollable columns styled like Calendar (the value is the canonical 24-hour
// "HH:mm[:ss]" string whatever the display cycle) and the Cancel/Apply/Clear footer.

export interface TimeUnitLabels {
  hours: string;
  minutes: string;
  seconds: string;
  period: string;
}

export const defaultTimeUnitLabels: TimeUnitLabels = {
  hours: "Hours",
  minutes: "Minutes",
  period: "AM/PM",
  seconds: "Seconds",
};

interface ColumnOption {
  value: number;
  label: string;
}

const pad = (value: number) => String(value).padStart(2, "0");
const range = (start: number, end: number): ColumnOption[] =>
  Array.from({ length: end - start + 1 }, (_, index) => ({
    label: pad(start + index),
    value: start + index,
  }));
const hours24 = range(0, 23);
const hours12 = [{ label: "12", value: 12 }, ...range(1, 11)];
const sixty = range(0, 59);

interface TimeColumnProps {
  id: string;
  label: string;
  options: readonly ColumnOption[];
  selected: number;
  onSelect: (value: number) => void;
  disabled?: boolean;
  readOnly?: boolean;
  invalid?: boolean;
  describedBy?: string;
  onEnter?: () => void;
}

const keyDelta = (key: string): number | "first" | "last" | undefined => {
  const deltas: Record<string, number | "first" | "last"> = {
    ArrowDown: 1,
    ArrowUp: -1,
    End: "last",
    Home: "first",
    PageDown: 5,
    PageUp: -5,
  };
  return deltas[key];
};

const TimeColumn = ({
  id,
  label,
  options,
  selected,
  onSelect,
  disabled,
  readOnly,
  invalid,
  describedBy,
  onEnter,
}: TimeColumnProps) => {
  const listRef = React.useRef<HTMLDivElement>(null);
  const blocked = Boolean(disabled || readOnly);
  // Centre the selection without animation, so reduced-motion needs no special case.
  React.useEffect(() => {
    const list = listRef.current;
    const item = list?.querySelector<HTMLElement>('[aria-selected="true"]');
    if (list && item) {
      list.scrollTop =
        item.offsetTop - (list.clientHeight - item.offsetHeight) / 2;
    }
  }, [selected]);

  const move = (delta: number | "first" | "last") => {
    const index = options.findIndex((option) => option.value === selected);
    let target = index + (typeof delta === "number" ? delta : 0);
    if (delta === "first") {
      target = 0;
    } else if (delta === "last") {
      target = options.length - 1;
    }
    const next = options[Math.min(Math.max(target, 0), options.length - 1)];
    if (next && next.value !== selected) {
      onSelect(next.value);
    }
  };

  return (
    <div
      ref={listRef}
      id={id}
      role="listbox"
      tabIndex={disabled ? -1 : 0}
      aria-label={label}
      aria-orientation="vertical"
      aria-disabled={disabled ? true : undefined}
      aria-readonly={readOnly ? true : undefined}
      aria-invalid={invalid ? true : undefined}
      aria-describedby={describedBy}
      aria-activedescendant={`${id}-${selected}`}
      data-slot="time-column"
      onKeyDown={(event) => {
        if (event.key === "Enter" && onEnter) {
          event.preventDefault();
          onEnter();
          return;
        }
        const delta = keyDelta(event.key);
        if (delta !== undefined) {
          event.preventDefault();
          if (!blocked) {
            move(delta);
          }
        }
      }}
      className={cn(
        "relative h-52 w-14 shrink-0 overflow-y-auto rounded-md border border-input bg-background p-1 shadow-xs outline-none [scrollbar-width:thin] focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-disabled:pointer-events-none aria-disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:bg-input/30 dark:aria-invalid:ring-destructive/40"
      )}
    >
      {options.map((option) => (
        <button
          key={option.value}
          id={`${id}-${option.value}`}
          type="button"
          role="option"
          tabIndex={-1}
          aria-selected={option.value === selected}
          disabled={disabled}
          onClick={() => {
            if (!blocked) {
              onSelect(option.value);
            }
          }}
          className="flex h-8 w-full items-center justify-center rounded-md text-sm tabular-nums outline-none hover:bg-accent hover:text-accent-foreground aria-selected:bg-primary aria-selected:text-primary-foreground aria-selected:hover:bg-primary/90"
        >
          {option.label}
        </button>
      ))}
    </div>
  );
};

export interface TimeFieldProps {
  id: string;
  label: string;
  value: string;
  onValueChange: (value: string) => void;
  precision: DateTimePrecision;
  hourCycle: HourCycle;
  locale?: Locale;
  unitLabels?: TimeUnitLabels;
  disabled?: boolean;
  readOnly?: boolean;
  invalid?: boolean;
  describedBy?: string;
  onEnter?: () => void;
}

/**
 * Building block shared with DateTimeRangePicker; its API may change.
 *
 * @internal
 */
export const TimeField = ({
  id,
  label,
  value,
  onValueChange,
  precision,
  hourCycle,
  locale,
  unitLabels = defaultTimeUnitLabels,
  disabled,
  readOnly,
  invalid,
  describedBy,
  onEnter,
}: TimeFieldProps) => {
  const parts = { hours: 0, minutes: 0, seconds: 0, ...parseTimeValue(value) };
  const { hour, pm } = to12Hour(parts.hours);
  const set = (part: TimePart, next: number) =>
    onValueChange(withTimePart(value, part, next, precision));
  const shared = { describedBy, disabled, invalid, onEnter, readOnly };
  const periods: ColumnOption[] = [
    { label: format(new Date(2000, 0, 1, 0), "a", { locale }), value: 0 },
    { label: format(new Date(2000, 0, 1, 12), "a", { locale }), value: 1 },
  ];

  return (
    <div
      data-slot="time-field"
      role="group"
      aria-labelledby={`${id}-label`}
      className="grid min-w-0 gap-1.5"
    >
      <span id={`${id}-label`} className="text-sm font-medium">
        {label}
      </span>
      <div className="flex gap-1.5">
        {hourCycle === 12 ? (
          <TimeColumn
            {...shared}
            id={`${id}-hours`}
            label={unitLabels.hours}
            options={hours12}
            selected={hour}
            onSelect={(next) => set("hours", from12Hour(next, pm))}
          />
        ) : (
          <TimeColumn
            {...shared}
            id={`${id}-hours`}
            label={unitLabels.hours}
            options={hours24}
            selected={parts.hours}
            onSelect={(next) => set("hours", next)}
          />
        )}
        <TimeColumn
          {...shared}
          id={`${id}-minutes`}
          label={unitLabels.minutes}
          options={sixty}
          selected={parts.minutes}
          onSelect={(next) => set("minutes", next)}
        />
        {precision === "second" ? (
          <TimeColumn
            {...shared}
            id={`${id}-seconds`}
            label={unitLabels.seconds}
            options={sixty}
            selected={parts.seconds}
            onSelect={(next) => set("seconds", next)}
          />
        ) : null}
        {hourCycle === 12 ? (
          <TimeColumn
            {...shared}
            id={`${id}-period`}
            label={unitLabels.period}
            options={periods}
            selected={pm ? 1 : 0}
            onSelect={(next) => set("hours", from12Hour(hour, next === 1))}
          />
        ) : null}
      </div>
    </div>
  );
};

export interface PickerFooterProps {
  showClear: boolean;
  canApply: boolean;
  whileTap: { scale: number } | false;
  labels: { apply: string; cancel: string; clear: string };
  onClear: () => void;
  onCancel: () => void;
  onApply: () => void;
}

/**
 * Shared with DateTimeRangePicker; its API may change.
 * @internal
 */
export const PickerFooter = ({
  showClear,
  canApply,
  whileTap,
  labels,
  onClear,
  onCancel,
  onApply,
}: PickerFooterProps) => (
  <div className="flex justify-end gap-2">
    {showClear ? (
      <Button
        type="button"
        variant="ghost"
        whileTap={whileTap}
        onClick={onClear}
      >
        {labels.clear}
      </Button>
    ) : null}
    <Button
      type="button"
      variant="outline"
      whileTap={whileTap}
      onClick={onCancel}
    >
      {labels.cancel}
    </Button>
    <Button
      type="button"
      disabled={!canApply}
      whileTap={whileTap}
      onClick={onApply}
    >
      {labels.apply}
    </Button>
  </div>
);

import type { Locale } from "date-fns";

export type DateTimePrecision = "minute" | "second";

export interface TimeParts {
  hours: number;
  minutes: number;
  seconds: number;
}

const pad = (value: number) => String(value).padStart(2, "0");

const timePattern = /^(\d{2}):(\d{2})(?::(\d{2}))?$/;

/** Parses a canonical time value ("HH:mm" or "HH:mm:ss"); undefined if invalid. */
export const parseTimeValue = (value: string): TimeParts | undefined => {
  const match = timePattern.exec(value);
  if (!match) {
    return undefined;
  }
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  const seconds = Number(match[3] ?? 0);
  if (hours > 23 || minutes > 59 || seconds > 59) {
    return undefined;
  }
  return { hours, minutes, seconds };
};

/** Formats a date's local time at the given precision. */
export const formatTimeValue = (
  date: Date,
  precision: DateTimePrecision
): string => {
  const base = `${pad(date.getHours())}:${pad(date.getMinutes())}`;
  return precision === "second" ? `${base}:${pad(date.getSeconds())}` : base;
};

/** Drops the parts a precision does not expose: milliseconds always, seconds for minutes. */
export const normalizeDateTime = (
  date: Date,
  precision: DateTimePrecision
): Date =>
  new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate(),
    date.getHours(),
    date.getMinutes(),
    precision === "second" ? date.getSeconds() : 0,
    0
  );

/**
 * Combines a calendar day with a local time.
 * shortcut: a time skipped by a DST gap resolves to the next valid local time, as
 * `new Date(y, m, d, h, min)` does; upgrade when a timeZone prop is added.
 */
export const mergeDateAndTime = (
  day: Date,
  time: TimeParts,
  precision: DateTimePrecision
): Date =>
  normalizeDateTime(
    new Date(
      day.getFullYear(),
      day.getMonth(),
      day.getDate(),
      time.hours,
      time.minutes,
      time.seconds,
      0
    ),
    precision
  );

/** A range is committable when both ends exist and `from` is not after `to`. */
export const isDateTimeRangeValid = (
  from: Date | undefined,
  to: Date | undefined
): boolean =>
  from !== undefined && to !== undefined && from.getTime() <= to.getTime();

/** Time shown before the user picks one: start of day, or the last moment for an end. */
export const defaultTimeValue = (
  kind: "start" | "end",
  precision: DateTimePrecision
): string => {
  const base = kind === "start" ? "00:00" : "23:59";
  if (precision === "minute") {
    return base;
  }
  return kind === "start" ? `${base}:00` : `${base}:59`;
};

export interface DateTimeRangeDraft {
  start?: Date;
  end?: Date;
  startTimeInvalid: boolean;
  endTimeInvalid: boolean;
  orderInvalid: boolean;
}

/**
 * Resolves a range draft. A single clicked day is a same-day range, so a time window
 * inside one day needs no second click. `orderInvalid` means both ends exist but the end
 * is before the start.
 */
export const resolveDateTimeRangeDraft = (
  days: { from?: Date; to?: Date } | undefined,
  startTime: string,
  endTime: string,
  precision: DateTimePrecision
): DateTimeRangeDraft => {
  const startParts = parseTimeValue(startTime);
  const endParts = parseTimeValue(endTime);
  const lastDay = days?.to ?? days?.from;
  const start =
    days?.from && startParts
      ? mergeDateAndTime(days.from, startParts, precision)
      : undefined;
  const end =
    lastDay && endParts
      ? mergeDateAndTime(lastDay, endParts, precision)
      : undefined;
  return {
    end,
    endTimeInvalid: endParts === undefined,
    orderInvalid: Boolean(start && end && !isDateTimeRangeValid(start, end)),
    start,
    startTimeInvalid: startParts === undefined,
  };
};

export type HourCycle = 12 | 24;

/**
 * An explicit cycle wins. Otherwise follow the locale's short time pattern: a day-period
 * token (a, b, B) means 12-hour. Without a locale this is 12-hour, like date-fns' default.
 */
export const resolveHourCycle = (
  locale?: Locale,
  explicit?: HourCycle
): HourCycle => {
  if (explicit) {
    return explicit;
  }
  const pattern = locale?.formatLong?.time({ width: "short" });
  return pattern && !/[abB]/.test(pattern) ? 24 : 12;
};

export const to12Hour = (hours: number): { hour: number; pm: boolean } => ({
  hour: hours % 12 || 12,
  pm: hours >= 12,
});

export const from12Hour = (hour: number, pm: boolean): number =>
  (hour % 12) + (pm ? 12 : 0);

export type TimePart = keyof TimeParts;

/** Returns the canonical "HH:mm[:ss]" value with one part replaced. */
export const withTimePart = (
  value: string,
  part: TimePart,
  next: number,
  precision: DateTimePrecision
): string => {
  const parts = {
    hours: 0,
    minutes: 0,
    seconds: 0,
    ...parseTimeValue(value),
    [part]: next,
  };
  const base = `${pad(parts.hours)}:${pad(parts.minutes)}`;
  return precision === "second" ? `${base}:${pad(parts.seconds)}` : base;
};
